import {createEngine} from './engine.js';
import {gradeSql} from './grader.js';
import {readState,STORAGE_KEY,mergeBackup,validateBackup,recordAttempt} from './state.js';

const appBase=new URL('../',import.meta.url);
const assetUrl=path=>new URL(path,appBase).href;
const loaded=readState();let state=loaded.state;
const app=document.querySelector('#app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',code:'m8 7-5 5 5 5m8-10 5 5-5 5m-3-14-2 20',book:'M12 6C9 3 5 3 2 4v15c4-1 7-1 10 2m0-15c3-3 7-3 10-2v15c-4-1-7-1-10 2V6',grid:'M3 3h7v7H3Zm11 0h7v7h-7ZM3 14h7v7H3Zm11 0h7v7h-7Z',chart:'M4 3v18h17M8 16v-4m5 4V8m5 8V5',arrow:'M4 12h15m-6-6 6 6-6 6',play:'m8 4 12 8-12 8Z',check:'m5 12 4 4L19 6',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',search:'m16 16 5 5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',bookmark:'M6 3h12v18l-6-4-6 4Z',database:'M4 5c0-4 16-4 16 0S4 9 4 5v14c0 4 16 4 16 0V5M4 12c0 4 16 4 16 0',sun:'M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',upload:'M12 16V4m-5 5 5-5 5 5M4 17v4h16v-4',close:'m6 6 12 12M6 18 18 6',help:'M9 8a3 3 0 1 1 4 3c-1 1-1 1-1 3m0 3h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',reset:'M3 4v6h6M4 9a9 9 0 1 1 0 8',link:'M9 15 15 9m-7 4-2 2a4 4 0 0 0 6 6l3-3m-6-9 3-3a4 4 0 0 1 6 6l-2 2',chevron:'m9 5 7 7-7 7'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.code}"/></svg>`;
let SQL,engineError,labEngine,labDataset=state.lab?.dataset||datasets[0].id,labSql=state.lab?.sql||'SELECT * FROM STUDENT;',labResult=null;
let editorDirty=false;let busy=false,activeId=null,feedback=null,result=null,exerciseTables=null,tableIndex=0,hintsShown=0,solutionSeen=false,viewMode='data',sourceFilter='all',offlineReady=false;
let filters={search:'',status:'all',kind:'all'},saveTimer,toastTimer,examTimer;
let evidence=[];
const nav=[['home','home',"Overview"],['practice','code',"Practice"],['lab','database',"SQL lab"],['learn','book',"Learn"],['sources','grid',"SQL reference"]];
const byId=id=>exercises.find(e=>e.id===id);
const datasetById=id=>datasets.find(d=>d.id===id)||datasets[0];
const visibleExercises=()=>exercises.filter(e=>e.level===state.level);
const route=()=>decodeURIComponent(location.hash.slice(1)||'home').split('/');
function go(to){if(location.hash===`#${to}`){render();return;}location.hash=to;}
function persist(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));return true;}catch{toast("Your browser could not save progress. Export a backup from Progress to keep a copy.",true);return false;}}
function toast(message,error=false){const el=document.querySelector('#toast');el.textContent=message;el.className=`show ${error?'error':''}`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className='',5000);}
function download(name,body,type='application/json'){const a=document.createElement('a');const url=URL.createObjectURL(new Blob([body],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function progress(){const list=visibleExercises();return {total:list.length,done:list.filter(e=>state.attempts[e.id]?.passed).length,independent:list.filter(e=>state.attempts[e.id]?.independent).length,wrong:list.filter(e=>state.attempts[e.id]?.tries>0&&!state.attempts[e.id].lastPassed).length};}
function nextExercise(){return byId(state.lastExercise)?.level===state.level&&!state.attempts[state.lastExercise]?.passed?byId(state.lastExercise):visibleExercises().find(e=>!state.attempts[e.id]?.passed)||visibleExercises()[0];}
function badge(e){return state.attempts[e.id]?.independent?"<span class=\"badge success\">Mastered</span>":state.attempts[e.id]?.passed?"<span class=\"badge\">Completed with help</span>":state.attempts[e.id]?.tries>0?"<span class=\"badge warm\">Try again</span>":`<span class="badge muted">${['',"Beginner","Intermediate","Challenge"][e.difficulty||1]}</span>`;}
function shell(content,current){document.documentElement.dataset.theme=state.theme;app.innerHTML=`
  <aside class="sidebar">
    <a href="#home" class="brand" aria-label="QueryPath home"><span class="brand-mark">${icon('database')}</span><span>QueryPath<small>Understand SQL for your exams</small></span></a>
    <div class="workspace-label">YOUR WORKSPACE</div>
    <nav aria-label="Main navigation">${nav.map(([id,i,title])=>`<a href="#${id}" aria-label="${title}" title="${title}" class="nav-item ${current===id?'active':''}" ${current===id?'aria-current="page"':''}>${icon(i)}<span>${title}</span>${current===id?'<span class="nav-dot"></span>':''}</a>`).join('')}</nav>
    <div class="sidebar-bottom"><a class="nav-item ${current==='progress'?'active':''}" href="#progress">${icon('chart')}<span>Progress & backups</span></a><div class="local-note"><span class="status-dot"></span><span>${offlineReady?"Offline learning is ready":navigator.onLine?"Progress saved on this device":"Currently offline"}</span></div><div class="sidebar-foot"><span>Every query is a step forward.</span><button class="icon-button" data-action="theme" aria-label="Switch to ${state.theme==='dark'?"light":"dark"} mode">${icon('sun')}</button></div></div>
  </aside>
  <div class="app-body"><header class="topbar"><div class="breadcrumb">Workspace <span>/</span> <strong>${({home:"Overview",practice:"Practice",exercise:"Practice",learn:"Learn",lesson:"Learn",lab:"SQL lab",sources:"SQL reference",progress:"Progress",exam:"Timed challenge"})[current]||"Workspace"}</strong></div><div class="topbar-actions"><label class="scope-select"><span>Practice scope</span><select id="level-select" aria-label="SQL practice scope"><option value="ig" ${state.level==='ig'?'selected':''}>Core queries · IG</option><option value="as" ${state.level==='as'?'selected':''}>Advanced SQL · AS / AL</option></select></label><a class="avatar" href="#progress" aria-label="View learning progress">Q</a></div></header>
  <main id="main" tabindex="-1">${content}</main><footer class="page-footer">SQL in your browser · Start exploring <span>QueryPath / Learn by doing</span></footer></div>
  <nav class="mobile-nav" aria-label="Mobile navigation">${nav.slice(0,4).map(([id,i,title])=>`<a href="#${id}" ${current===id?'aria-current="page"':''} class="${current===id?'active':''}">${icon(i)}<span>${title.replace('SQL lab','Lab')}</span></a>`).join('')}<a href="#progress" ${current==='progress'?'aria-current="page"':''}>${icon('chart')}<span>Progress</span></a></nav>`;
}
function heading(kicker,title,text,action=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1>${text?`<p>${text}</p>`:''}</div>${action}</div>`;}
function home(){const p=progress(),next=nextExercise();const list=lessons.filter(l=>l.level===state.level);return `
  ${heading('A LITTLE QUERY. A NEW DISCOVERY.',"Ask your data a question.","Turn IG, AS and A Level SQL knowledge into results you can see.",`<a href="#sources" class="text-link">Open SQL reference ${icon('arrow')}</a>`)}
  <section class="hero"><div class="hero-copy"><span class="hero-pill"><span></span>Exam SQL, running in your browser</span><h2>Turn curiosity<br>into a query.</h2><p>Put SELECT, filters and totals into practice.<br class="desktop-only">Run a query, explore the results, and apply what you learn to exam questions.</p><div class="hero-actions"><a class="button light" href="#lab">Open SQL lab ${icon('arrow')}</a><a class="hero-secondary" href="#exercise/${next.id}">${p.done?"Continue learning":"Write your first query"} ${icon('chevron')}</a></div><div class="hero-caption">Real data tables <i></i> Instant results <i></i> Reset anytime</div></div>
  <div class="hero-visual" aria-label="Example SQL query and result"><div class="mini-editor"><div class="mini-editor-bar"><span class="window-dots">● ● ●</span><span>first_query.sql</span><span>SQL</span></div><pre><span class="line">1</span> <b>SELECT</b> Title, Price
<span class="line">2</span> <b>FROM</b> BOOK
<span class="line">3</span> <b>WHERE</b> Price &lt; <em>15</em>;</pre><div class="mini-editor-foot">${icon('check')} Query complete <span>3 rows</span></div></div><div class="mini-result"><div class="mini-result-label">${icon('grid')} Query results <span>Example preview</span></div><table><thead><tr><th>Title</th><th>Price</th></tr></thead><tbody><tr><td>Ocean Atlas</td><td>12.50</td></tr><tr><td>Small Worlds</td><td>9.80</td></tr><tr><td>The Quiet Forest</td><td>14.00</td></tr></tbody></table></div><span class="visual-spark spark-one">+</span><span class="visual-spark spark-two">+</span></div></section>
  <div class="stats-row"><a href="#progress" class="stat-card"><span class="stat-icon">${icon('check')}</span><div><strong>${p.done}<small> / ${p.total}</small></strong><span>Tasks completed</span></div><div class="stat-trail">From understanding to practice</div></a><a href="#progress" class="stat-card"><span class="stat-icon blue">${icon('chart')}</span><div><strong>${p.independent}</strong><span>Solved independently</span></div><div class="stat-trail">Every attempt counts</div></a><button data-action="review" class="stat-card"><span class="stat-icon amber">${icon('reset')}</span><div><strong>${p.wrong}</strong><span>Tasks to revisit</span></div><span class="stat-trail">Review and discover more</span></button></div>
  <div class="home-columns"><section><div class="section-heading"><h2>Your next step</h2><a href="#learn">Explore all lessons ${icon('arrow')}</a></div><a class="continue-card" href="#exercise/${next.id}"><span class="number-tag">${String(visibleExercises().indexOf(next)+1).padStart(2,'0')}</span><div><div class="tiny-label">${p.done?'CONTINUE EXPLORING':'START HERE'}</div><h3>${esc(next.title)}</h3><p>${esc(next.brief)}</p><span class="duration">${icon('clock')} ${next.minutes||5} min · ${esc(datasetById(next.dataset).name)}</span></div><span class="round-arrow">${icon('arrow')}</span></a><div class="section-heading spaced"><h2>Start with a real scenario</h2><span class="muted-text">Choose a dataset and explore</span></div><div class="dataset-cards">${datasets.map((d,i)=>`<button class="dataset-card" data-action="dataset" data-id="${d.id}"><span class="dataset-illustration tint-${i}">${icon(i===0?'book':i===1?'grid':'chart')}</span><strong>${esc(d.name)}</strong><span>${esc(d.description)}</span><small>Open dataset ${icon('arrow')}</small></button>`).join('')}</div></section>
  <section class="path-card"><div class="section-heading"><h2>Understand data, step by step</h2><span class="badge muted">${state.level==='ig'?"Core path":"Advanced path"}</span></div><div class="learning-path">${list.slice(0,4).map((l,i)=>{const done=l.exerciseIds.every(id=>state.attempts[id]?.passed);return `<a href="#lesson/${l.id}" class="path-step"><span class="step-number ${done?'done':''}">${done?icon('check'):i+1}</span><div><h3>${esc(l.title)}</h3><p>${esc(l.subtitle)}</p><small>${l.minutes} min · ${l.exerciseIds.length} exercises</small></div>${icon('chevron')}</a>`;}).join('')}</div><a href="#learn" class="button secondary wide">Browse all  ${list.length}  lessons ${icon('arrow')}</a><div class="path-tip">${icon('help')} Follow your curiosity. Start with the question you want to answer.</div></section></div>`;}
function exerciseCards(list){return list.length?list.map(e=>`<article class="task-card"><div class="task-top"><span class="task-kind">${e.kind==='sql'?"Write SQL":e.kind==='predict'?"Predict results":"Understand concepts"}</span><button class="icon-button ${state.bookmarks.includes(e.id)?'bookmarked':''}" data-action="bookmark" data-id="${e.id}" aria-label="${state.bookmarks.includes(e.id)?"Remove bookmark":"Bookmark"}: ${esc(e.title)}" aria-pressed="${state.bookmarks.includes(e.id)}">${icon('bookmark')}</button></div><a href="#exercise/${e.id}"><h3>${esc(e.title)}</h3><p>${esc(e.brief)}</p></a><div class="task-meta"><span>${icon('clock')} ${e.minutes||5} min</span>${badge(e)}</div><a href="#exercise/${e.id}" class="task-start">${state.attempts[e.id]?"Try again":"Start task"} ${icon('arrow')}</a></article>`).join(''):`<div class="empty-state">${icon('search')}<h3>No matching tasks</h3><p>Try a shorter search or clear the current filters.</p><button class="button secondary" data-action="clear-filters">Clear filters</button></div>`;}
function filteredExercises(){return visibleExercises().filter(e=>`${e.title} ${e.brief} ${e.prompt} ${(e.objectives||[]).join(' ')}`.toLowerCase().includes(filters.search.toLowerCase())&&(filters.kind==='all'||e.kind===filters.kind)&&(filters.status==='all'||filters.status==='todo'&&!state.attempts[e.id]?.passed||filters.status==='wrong'&&state.attempts[e.id]?.tries>0&&!state.attempts[e.id].lastPassed||filters.status==='saved'&&state.bookmarks.includes(e.id)));}
function practice(){return `${heading('PRACTICE MAKES IT CLICK',"Make every query count.","Choose a task, explore the data, and write your solution.",`<a href="#exam" class="button secondary">${icon('clock')} Timed challenge</a>`)}<div class="filter-panel"><label class="search-field">${icon('search')}<input id="task-search" type="search" placeholder="Search SELECT, stock, joins…" aria-label="Search practice tasks" value="${esc(filters.search)}"></label><div class="filter-tabs" role="group" aria-label="Task status">${[['all',"All"],['todo',"To explore"],['wrong',"Try again"],['saved',"Bookmarked"]].map(([id,label])=>`<button data-action="filter" data-value="${id}" aria-pressed="${filters.status===id}" class="${filters.status===id?'selected':''}">${label}</button>`).join('')}</div><select id="kind-filter" aria-label="Task type"><option value="all">All task types</option>${[['sql',"Write SQL"],['predict',"Predict results"],['concept',"Understand concepts"]].map(([id,t])=>`<option value="${id}" ${filters.kind===id?'selected':''}>${t}</option>`).join('')}</select></div><p class="result-count" id="task-count">${filteredExercises().length} tasks · ${state.level==='ig'?"Single-table query basics":"Related data and maintenance"}</p><div class="task-grid" id="task-list">${exerciseCards(filteredExercises())}</div>`;}
function learn(){return `${heading('UNDERSTAND. TRY. REMEMBER.',"Less memorising. More understanding.","Each lesson starts with a question and explains SQL through examples you can run.")}<div class="lesson-grid">${lessons.filter(l=>l.level===state.level).map((l,i)=>{const count=l.exerciseIds.filter(id=>state.attempts[id]?.passed).length;return `<article class="lesson-card"><div class="lesson-top"><span class="lesson-number">${String(i+1).padStart(2,'0')}</span><span class="muted-text">${l.minutes} min</span></div><h2><a href="#lesson/${l.id}">${esc(l.title)}</a></h2><p>${esc(l.subtitle)}</p><div class="keyword-tags">${l.keywords.map(k=>`<code>${esc(k)}</code>`).join('')}</div><div class="progress-line"><span style="width:${count/l.exerciseIds.length*100}%"></span></div><div class="lesson-bottom"><span>${count} / ${l.exerciseIds.length} tasks completed</span><a href="#lesson/${l.id}">Open lesson ${icon('arrow')}</a></div></article>`;}).join('')}</div>`;}
function lesson(id){const l=lessons.find(l=>l.id===id);if(!l)return notFound();return `<a href="#learn" class="back-link">← Back to lessons</a>${heading('LEARNING NOTE',esc(l.title),esc(l.subtitle))}<div class="reading-layout"><article class="reading-card">${l.body.map((p,i)=>`<div class="reading-section"><span class="reading-number">0${i+1}</span><p>${esc(p)}</p></div>`).join('')}<div class="code-sample"><div><span>Run this example yourself</span><button class="text-link" data-action="lesson-lab" data-id="${l.id}">Open in lab ${icon('arrow')}</button></div><pre><code>${esc(l.example)}</code></pre></div><div class="note">${icon('help')} Explore the result, then change the fields, conditions or sorting. Experiment to understand how the query works.</div></article><aside class="lesson-tasks"><h2>Try it yourself</h2>${l.exerciseIds.map(id=>byId(id)).filter(Boolean).map(e=>`<a href="#exercise/${e.id}" class="lesson-task"><span>${esc(e.title)}<small>${e.minutes||5} min</small></span>${state.attempts[e.id]?.passed?icon('check'):icon('arrow')}</a>`).join('')}<a href="#sources" class="text-link">Syntax and sources ${icon('link')}</a></aside></div>`;}
function dataTable(columns,rows,{caption='',empty="No matching records",max=100}={}){return `<div class="table-scroll" tabindex="0" role="region" aria-label="${esc(caption||"Data table")}" title="Scroll horizontally to explore a wide table"><table class="data-table">${caption?`<caption>${esc(caption)}</caption>`:''}<thead><tr><th class="row-index" scope="col">#</th>${columns.map(c=>`<th scope="col">${esc(typeof c==='string'?c:c.name)}</th>`).join('')}</tr></thead><tbody>${rows.slice(0,max).map((r,i)=>`<tr><th scope="row" class="row-index">${i+1}</th>${r.map(v=>`<td>${v===null?'<span class="null-value">NULL</span>':esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table>${!rows.length?`<div class="table-empty">${empty}</div>`:''}</div>${rows.length>max?`<p class="table-limit">Showing the first  ${max}  of  ${rows.length}  rows. Export CSV to view all results.</p>`:''}`;}
function taskTables(tables,e){const d=datasetById(e.dataset);const main=e.focusTables?.[0]||/\b(?:FROM|UPDATE|INTO)\s+([a-z0-9_$]+)/i.exec(e.solution||e.starter||'')?.[1]||d.tables[0];const preferred=tables.find(t=>t.name.toLowerCase()===main.toLowerCase());if(e.level==='ig'&&preferred)return [preferred];const ordered=displayTables(tables,d);return preferred?[preferred,...ordered.filter(t=>t!==preferred)]:ordered;}
function displayTables(tables,d){const order=d.tables;return [...tables].sort((a,b)=>(order.includes(a.name)?order.indexOf(a.name):999)-(order.includes(b.name)?order.indexOf(b.name):999));}
function databasePanel(tables){if(!tables.length)return "<div class=\"empty-inline\">This database has no tables yet. Try CREATE TABLE or reset the sample data.</div>";tableIndex=Math.min(tableIndex,tables.length-1);const t=tables[tableIndex];return `<div class="table-tabs" role="group" aria-label="Choose a data table">${tables.map((t,i)=>`<button data-action="table" data-index="${i}" aria-pressed="${i===tableIndex}" class="${i===tableIndex?'selected':''}">${icon('grid')} ${esc(t.name)} <small>${t.rows.length}</small></button>`).join('')}</div><details class="schema-details"><summary>Fields and types <span>${t.columns.length} fields · expand</span></summary><div class="schema-chips">${t.columns.map(c=>`<span><code>${esc(c.name)}</code><small>${esc(c.type||'—')}${c.pk?" · primary key":''}</small></span>`).join('')}</div></details>${dataTable(t.columns,t.rows,{caption:t.name})}`;}
function outputPanel(value){if(!value)return `<div class="output-placeholder">${icon('play')}<div><strong>Ready to find an answer?</strong><p>Run SQL to see the results here.</p></div></div>`;if(value.error)return `<div class="feedback error" role="alert"><strong>This statement needs a change</strong><p>${esc(value.error)}</p></div>`;return `<div class="output-summary"><span class="success-text">${icon('check')} ${value.columns?.length?`Query complete · ${value.rows.length} rows`:"Execution complete"}</span><span>${esc(value.message||'')}</span>${value.columns?.length?"<button class=\"text-link\" data-action=\"csv\">Export CSV</button>":''}</div>${value.notes?.length?`<div class="compat-notes">${value.notes.map(n=>`<p>${esc(n)}</p>`).join('')}</div>`:''}${value.columns?.length?dataTable(value.columns,value.rows,{caption:"Query results"}):`<div class="mutation-summary">${icon('database')}<p>${esc(value.message||`Data updated. ${value.affected!=null?"Affected  "+value.affected+"  records.":''}`)} Explore the table above to see what changed.</p></div>`}`;}
function editor(sql,{lab=false,readonly=false}={}){return `<section class="editor-card"><div class="editor-header"><span>${icon('code')} ${lab?'playground.sql':'your_query.sql'}</span><div><button class="icon-button" data-action="font" aria-label="Enlarge or reset the SQL font">A↕</button><button class="icon-button" data-action="copy" aria-label="Copy SQL">${icon('link')}</button><button class="icon-button" data-action="reset-code" aria-label="Restore starting SQL">${icon('reset')}</button></div></div><div class="editor-area"><div class="line-numbers" aria-hidden="true">${sql.split('\n').map((_,i)=>i+1).join('\n')}</div><textarea id="sql-editor" aria-label="SQL editor" aria-describedby="editor-help" spellcheck="false" autocapitalize="off" autocomplete="off" autocorrect="off" ${readonly?'readonly':''} wrap="off">${esc(sql)}</textarea></div>${!readonly?`<div class="keyword-toolbar" aria-label="Insert a SQL keyword">${['SELECT','FROM','WHERE','AND','ORDER BY',...(state.level==='as'?['INNER JOIN','GROUP BY']:[])].map(k=>`<button data-action="insert" data-text="${k} ">${k}</button>`).join('')}</div>`:''}<p id="editor-help" class="sr-only">Press Ctrl or Command plus Enter to run SQL. Tab indents; press Escape followed by Tab to leave the editor.</p><div class="editor-actions"><span class="keyboard-hint">Ctrl / ⌘ + Enter to run · Esc + Tab to leave</span><div><button class="button ${lab?'primary':'secondary'}" data-action="run" ${busy?'disabled':''}>${icon('play')} ${busy?"Running…":"Run SQL"}</button>${!lab&&!readonly?`<button class="button primary" data-action="submit" ${busy?'disabled':''}>${icon('check')} Check result</button>`:''}</div></div></section>`;}
function feedbackHtml(){if(!feedback)return '';return `<section class="feedback ${feedback.passed?'success':'error'}" id="answer-feedback" tabindex="-1" role="status"><div class="feedback-title">${icon(feedback.passed?'check':'help')}<h3>${feedback.passed?"You did it. The data checks out.":"Try a small change and check again."}</h3></div><p>${esc(feedback.detail)}</p>${feedback.passed?`<p>${esc(byId(activeId)?.explanation||'')}</p>${solutionSeen?"<small>A reference answer was used, so this counts as assisted completion.</small>":''}<button class="button primary" data-action="next">Next task ${icon('arrow')}</button>`:''}</section>`;}
async function exerciseView(id){const e=byId(id);if(!e){shell(notFound(),'practice');return;}if(e.level!==state.level){state.level=e.level;persist();}if(activeId!==id){activeId=id;feedback=null;result=null;editorDirty=false;exerciseTables=null;hintsShown=state.attempts[id]?.hints||0;solutionSeen=!!state.attempts[id]?.assisted;tableIndex=0;}state.lastExercise=id;persist();
  const d=datasetById(e.dataset);let tables=[];try{const db=await createEngine({SQL,level:e.level,seed:d.seed+(e.setup?'\n'+e.setup:'')});tables=taskTables(db.tables(),e);db.close();}catch(err){result={error:err.message};}
  if(route()[0]!=='exercise'||route()[1]!==id)return;if(exerciseTables)tables=exerciseTables;
  shell(`<a href="#practice" class="back-link">← Back to practice</a><div class="exercise-heading"><div><span class="eyebrow">${esc(d.name)} / ${e.kind==='sql'?'WRITE A QUERY':e.kind==='predict'?'READ THE RESULT':'UNDERSTAND THE DATA'}</span><h1>${esc(e.title)}</h1></div><button class="button secondary" data-action="bookmark" data-id="${id}" aria-pressed="${state.bookmarks.includes(id)}">${icon('bookmark')} ${state.bookmarks.includes(id)?"Bookmarked":"Bookmark task"}</button></div><div class="workspace"><aside class="task-panel"><div class="task-panel-label">${icon('book')} Your task ${badge(e)}</div><p class="english-prompt" lang="en">${esc(e.prompt)}</p><p class="task-brief">${esc(e.brief)}</p><div class="objectives"><h3>What you will use</h3><div class="keyword-tags">${(e.objectives||[]).map(s=>`<code>${esc(s)}</code>`).join('')}</div></div><div class="task-help"><h3>Need a hint?</h3><div id="hints">${(e.hints||[]).slice(0,hintsShown).map((h,i)=>`<p><span>${i+1}</span>${esc(h)}</p>`).join('')}</div><button class="button secondary wide" data-action="hint" ${hintsShown>=(e.hints||[]).length?'disabled':''}>${icon('help')} ${hintsShown>=(e.hints||[]).length?"All hints shown":`Show hint  ${hintsShown+1} / ${(e.hints||[]).length}`}</button><button class="text-link solution-link" data-action="solution">View explanation and answer</button></div><div class="task-scope">${icon('database')} Each run starts with the original data. Try things out.</div></aside><div class="work-main"><section class="data-card"><div class="card-title"><h2>${icon('database')} Explore the data</h2><span>${esc(d.name)}</span></div><div id="database-panel">${databasePanel(tables)}</div></section>${e.kind==='sql'?editor(state.drafts[id]??e.starter??''):e.kind==='predict'?`<div class="code-sample"><div>Read this query</div><pre><code>${esc(e.starter||e.solution)}</code></pre></div><section class="answer-card"><label for="prediction">Write your predicted result</label><p>Use one record per line, with comma-separated fields and no header.</p><textarea id="prediction" rows="4" placeholder="For example: Alex,85" spellcheck="false">${esc(state.drafts[id]||'')}</textarea><button class="button primary" data-action="submit">${icon('check')} Check prediction</button></section>`:`<section class="answer-card"><fieldset><legend>Choose your answer</legend>${e.options.map((o,i)=>`<label class="choice"><input type="radio" name="concept" value="${i}" ${state.drafts[id]===String(i)?'checked':''}><span><b>${String.fromCharCode(65+i)}.</b> ${esc(o)}</span></label>`).join('')}</fieldset><button class="button primary" data-action="submit">${icon('check')} Check answer</button></section>`}<div id="feedback-region">${feedbackHtml()}</div>${e.kind==='sql'?`<section class="result-card"><div class="card-title"><h2>${icon('grid')} Results</h2><span>Runs on your device</span></div><div id="output-panel">${outputPanel(result)}</div></section>`:''}</div></div>`,'practice');
}
async function ensureLab(){if(labEngine)return;const d=datasetById(labDataset);try{labEngine=await createEngine({SQL,level:state.level,seed:d.seed,snapshot:state.lab?.dataset===d.id?state.lab.snapshot:undefined});}catch(error){labEngine=await createEngine({SQL,level:state.level,seed:d.seed});toast("The lab snapshot could not be restored, so the sample data was loaded. Your progress and SQL draft are preserved.",true);}if(!state.lab?.sql)labSql=`SELECT *\nFROM ${d.tables[0]};`;state.lab={dataset:d.id,sql:labSql,snapshot:labEngine.export()};persist();}
async function lab(){await ensureLab();if(route()[0]!=='lab')return;shell(`${heading('YOUR SQL PLAYGROUND',"One question. Many ways to explore.","Work with data and see the results immediately. Your changes stay in this browser.",`<button class="button secondary" data-action="reset-db">${icon('reset')} Reset data</button>`)}<div class="lab-toolbar"><label>Sample dataset <select id="dataset-select" aria-label="Lab dataset">${datasets.map(d=>`<option value="${d.id}" ${d.id===labDataset?'selected':''}>${esc(d.name)}</option>`).join('')}</select></label><span class="muted-text">${esc(datasetById(labDataset).description)}</span><button class="text-link" data-action="templates">Try a query template ${icon('arrow')}</button></div><div class="lab-layout"><div class="lab-main">${editor(labSql,{lab:true})}<section class="result-card"><div class="card-title"><h2>${icon('grid')} Query results</h2><span id="lab-save-status">${state.lab?"Previous experiment restored":"Restore sample data anytime"}</span></div><div id="output-panel">${outputPanel(labResult)}</div></section></div><aside class="data-card lab-data"><div class="card-title"><h2>${icon('database')} Data explorer</h2><span>${esc(labEngine.export().databaseName||"Local sandbox")}</span></div><div id="database-panel">${databasePanel(displayTables(labEngine.tables(),datasetById(labDataset)))}</div><div class="lab-note"><strong>Try changing one condition</strong><p>Run SELECT * to explore the data. Then select fields, add WHERE, and see what changes at each step.</p><a href="#sources" class="text-link">Open SQL reference ${icon('arrow')}</a></div></aside></div><div class="note">${icon('help')} ${state.level==='ig'?"You are using core queries. Choose Advanced SQL in the top-right menu to try joins, table creation and data maintenance.":"You can query two tables, create tables and maintain data. CREATE DATABASE opens a new empty database; reset to restore the sample data."}</div>`,'lab');}
function sources(){const ig=state.level==='ig';const rows=ig?[["Select fields",'SELECT field FROM Table;',"Choose the output columns, then name the table."],["Filter records","WHERE Score >= 80 AND Active = TRUE","AND requires both conditions; OR requires at least one."],["Sort results",'ORDER BY Score DESCENDING',"DESC also means descending. ASCENDING and ASC mean ascending."],["Count records",'SELECT COUNT(*) FROM Table;',"COUNT counts records; SUM(field) adds values."]]:[["Join two tables",'FROM A INNER JOIN B ON A.ID = B.ID',"Match records using their related fields and an explicit join condition."],["Group summaries",'SELECT ClubID, AVG(Score) FROM STUDENT GROUP BY ClubID;',"Calculate a separate result for each group."],["Match text","WHERE FirstName LIKE 'A%'","% matches any number of characters; _ matches one character."],["Maintain data","UPDATE STUDENT SET Score = 90 WHERE StudentID = 1;","INSERT adds, UPDATE changes, and DELETE removes records."],["Define structure",'CREATE TABLE TEAM (ID INTEGER, Name VARCHAR(30), PRIMARY KEY(ID));',"Use ALTER TABLE to add fields, primary keys and foreign keys."]];return `${heading('A REFERENCE, NOT A RULEBOOK',"A reference for your next query.","Connect syntax with what it does. Understand it, then try it.")}<section class="reference-grid">${rows.map(([title,sql,desc])=>`<article class="reference-card"><h2>${title}</h2><pre><code>${esc(sql)}</code></pre><p>${desc}</p></article>`).join('')}</section><section class="reference-note"><h2>Details that make queries clearer</h2><ul><li>Quote text values. Write numbers without quotes. Single quotes are recommended; double-quoted text from exam examples is also supported.</li><li>COUNT(*) counts records; SUM(field) totals a field. AS also includes AVG(field).</li><li>Use ORDER BY when row order matters. A sorting field can be omitted from the SELECT list.</li><li>Check the filter boundaries, output columns and which records should appear in the result.</li><li>The selected practice scope determines which SQL features are available.</li></ul></section><details class="evidence-section"><summary><span><strong>Sources and exam coverage</strong><small>Explore syllabuses, paper audits and syntax evidence</small></span><span class="badge">41 papers + mark schemes</span></summary><div class="evidence-content"><p>For IGCSE 0478 (2026–2028) and AS / full A Level 9618 (2026 and 2027–2029). SQL is part of the AS foundation within the full A Level. Each historical syntax example is linked to its paper and mark scheme.</p><div class="source-links"><a href="https://www.cambridgeinternational.org/Images/697167-2026-2028-syllabus.pdf" target="_blank" rel="noopener">0478 syllabus · §9 ↗</a><a href="https://www.cambridgeinternational.org/Images/697372-2026-syllabus.pdf" target="_blank" rel="noopener">9618 2026 · §8.3 ↗</a><a href="https://www.cambridgeinternational.org/Images/721397-2027-2029-syllabus.pdf" target="_blank" rel="noopener">9618 2027–2029 · §8.3 ↗</a><a href="./docs/research/ig-paper-audit.md" target="_blank" rel="noopener">IG paper audit ↗</a><a href="./docs/research/as-paper-audit.md" target="_blank" rel="noopener">AS paper audit ↗</a></div><p>Reviewed on 24 October 2026: 21 IG Paper 2 papers and 20 AS Paper 1 papers with distinct SQL content, each checked against its mark scheme. Practice exercises are original and provide immediate learning feedback.</p><div class="filter-tabs" role="group" aria-label="Filter source evidence">${[['all',"All"],['0478','IG'],['9618','AS / AL']].map(([id,label])=>`<button data-action="source-filter" data-value="${id}" aria-pressed="${sourceFilter===id}" class="${sourceFilter===id?'selected':''}">${label}</button>`).join('')}</div><div id="evidence-list">${evidenceList()}</div></div></details><section class="reference-note"><h2>About the SQL lab</h2><p>SQL runs in SQLite, with compatibility handling for exam sorting keywords, Boolean values and dates. Schema operations check primary and foreign keys. VARCHAR(n) declares a length, while SQLite stores text without enforcing that length automatically.</p><p>Your learning records are stored in this browser. Export a backup to move them between devices, browsers or site addresses.</p></section>`;}
function evidenceList(){const list=evidence.filter(e=>sourceFilter==='all'||e.id.startsWith(sourceFilter));return list.length?list.map(e=>`<article class="evidence-row"><div><strong>${esc(e.id.replace(/_/g,' '))}</strong><span>Q${esc(e.question)} · QP p.${esc(e.pages.qp.join(', '))} / MS p.${esc(e.pages.ms.join(', '))}</span><p>${esc(e.analysis)}</p><div class="keyword-tags">${e.topics.map(k=>`<code>${esc(k)}</code>`).join('')}</div>${e.allowances?.length?`<details><summary>Syntax notes</summary>${e.allowances.map(a=>`<p>${esc(a)}</p>`).join('')}</details>`:''}</div><div><a href="${esc(e.qpUrl)}" target="_blank" rel="noopener">Question paper ↗</a><a href="${esc(e.msUrl)}" target="_blank" rel="noopener">Mark scheme ↗</a></div></article>`).join(''):"<p>Loading research records. You can also open the paper audits above.</p>";}
function recoveryAvailable(){try{return !!localStorage.getItem(STORAGE_KEY+'.recovery');}catch{return false;}}
function progressPage(){const p=progress();return `${heading('YOUR LEARNING, YOUR PACE',"Every attempt counts.","Track your progress and build on what you understand.",`<button class="button secondary" data-action="export">${icon('download')} Export learning records</button>`)}<div class="stats-row"><div class="stat-card"><span class="stat-icon">${icon('check')}</span><div><strong>${p.done}</strong><span>Completed tasks</span></div></div><div class="stat-card"><span class="stat-icon blue">${icon('chart')}</span><div><strong>${p.independent}</strong><span>Solved independently</span></div></div><div class="stat-card"><span class="stat-icon amber">${icon('reset')}</span><div><strong>${p.wrong}</strong><span>To review</span></div></div></div><div class="progress-layout"><section class="panel"><div class="section-heading"><h2>Recent activity</h2><button class="text-link" data-action="review">Review mistakes ${icon('arrow')}</button></div>${state.history.length?state.history.slice(-12).reverse().map(a=>{const e=byId(a.id);return e?`<a href="#exercise/${e.id}" class="history-row"><span class="history-status ${a.passed?'success-text':'warm-text'}">${icon(a.passed?'check':'reset')}</span><div><strong>${esc(e.title)}</strong><small>${new Date(a.at).toLocaleString('en-GB',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})} · ${a.assisted?"Reference answer used":"Independent attempt"}</small></div><span>${a.passed?"Completed":"Try again"}</span>${icon('chevron')}</a>`:'';}).join(''):`<div class="empty-state">${icon('chart')}<h3>Your first query is worth recording</h3><p>Complete a task to see your activity here.</p><a href="#practice" class="button primary">Start exploring ${icon('arrow')}</a></div>`}</section><section class="panel settings-panel"><h2>Take your progress with you</h2><p>Export a JSON backup and import it on another device. Importing merges your completed tasks with your current progress.</p><button class="button secondary wide" data-action="export">${icon('download')} Export backup</button><label class="button secondary wide file-button">${icon('upload')} Import backup<input type="file" id="import-file" accept=".json,application/json"></label>${recoveryAvailable()?"<button class=\"button secondary wide\" data-action=\"recovery\">Export recovery file</button>":''}<div class="settings-divider"></div><h2>Make learning comfortable</h2><button class="button secondary wide" data-action="theme">${icon('sun')} ${state.theme==='dark'?"Switch to light mode":"Switch to dark mode"}</button><button class="button secondary wide" data-action="install">${icon('download')} Offline use & installation</button><a class="button secondary wide" href="#sources">${icon('book')} Syntax and sources</a><div class="settings-divider"></div><button class="text-link danger-text" data-action="clear-progress">Clear local learning records</button><p class="small-note">Records are stored in this browser. Export a backup before clearing browser data.</p></section></div>`;}
function exam(){const x=state.exam;if(!x||x.finished){const report=x?.finished;return `${heading('A SMALL CHALLENGE',"Make time to focus.","Solve 5 short tasks independently in 15 minutes. Review your feedback at the end.")}<section class="challenge-start panel"><span class="challenge-icon">${icon('clock')}</span><h2>${report?"Challenge complete":"Ready to check your understanding?"}</h2>${report?`<p class="challenge-score">${x.ids.filter(id=>x.answers[id]?.passed).length}<span> / ${x.ids.length}</span></p><p>Review your results and revisit any tasks you want to practise.</p><div class="challenge-results">${x.ids.map(id=>`<a href="#exercise/${id}"><span>${esc(byId(id)?.title||id)}</span><span>${x.answers[id]?.passed?"✓ Solved":"↻ Practise again"}</span></a>`).join('')}</div>`:"<p>Tasks are selected from your current scope and include writing, reading and understanding SQL. The timer continues if you close the page. Answers and progress are saved on this device.</p>"}<button class="button primary" data-action="start-exam">${report?"Try another challenge":"Start a 15-minute challenge"} ${icon('arrow')}</button></section>`;}
const e=byId(x.ids[x.index]);if(!e){state.exam=null;persist();return exam();}return `${heading('FOCUS MODE',`Task  ${x.index+1} / ${x.ids.length}`,esc(e.title),'<span class="exam-clock" id="exam-clock"></span>')}<div class="exam-progress">${x.ids.map((id,i)=>`<button data-action="exam-index" data-index="${i}" class="${i===x.index?'active':''}" aria-label="Go to question  ${i+1}  ">${i+1}${x.answers[id]?.submitted?' ✓':''}</button>`).join('')}</div><section class="panel exam-panel"><p class="english-prompt" lang="en">${esc(e.prompt)}</p><p>${esc(e.brief)}</p><details id="exam-data"><summary>View  ${esc(datasetById(e.dataset).name)}  data</summary><div id="exam-table-content">Preparing data…</div></details>${e.kind==='sql'?`<label for="exam-answer">Your SQL</label><textarea id="exam-answer" class="exam-answer" rows="7" spellcheck="false" autocapitalize="off">${esc(x.answers[e.id]?.value??e.starter??'')}</textarea>`:e.kind==='predict'?`<pre class="code-sample">${esc(e.starter||e.solution)}</pre><label for="exam-answer">Predicted result (one record per line, comma-separated fields)</label><textarea id="exam-answer" rows="4">${esc(x.answers[e.id]?.value||'')}</textarea>`:`<fieldset><legend>Choose an answer</legend>${e.options.map((o,i)=>`<label class="choice"><input type="radio" name="exam-concept" value="${i}" ${x.answers[e.id]?.value===String(i)?'checked':''}><span>${esc(o)}</span></label>`).join('')}</fieldset>`}<div class="exam-actions"><button class="button secondary" data-action="exam-save">Save answer ${icon('check')}</button><button class="button primary" data-action="${x.index<x.ids.length-1?'exam-next':'finish-exam'}">${x.index<x.ids.length-1?"Next task":"Finish and view results"} ${icon('arrow')}</button></div><p class="small-note" id="exam-save-note">${x.answers[e.id]?.submitted?"Answer saved. You can keep editing.":"Answers save automatically and are checked at the end."}</p></section><button class="text-link" data-action="finish-exam">Finish challenge early</button>`;}
function notFound(){return `<div class="empty-state"><h1>This page could not be found</h1><p>Return to your workspace to keep learning.</p><a class="button primary" href="#home">Back to overview</a></div>`;}
async function render(){clearInterval(examTimer);const [page,id]=route();if(!SQL){shell(`<div class="empty-state">${engineError?`<h1>The SQL engine could not start</h1><p>${esc(engineError)}</p><button class="button primary" data-action="reload">Reload</button>`:"<h1>Preparing data and the SQL engine…</h1><p>You can start practising as soon as loading completes.</p>"}</div>`,page);return;}if(page==='exercise')await exerciseView(id);else if(page==='lab')await lab();else{const renderer={home,practice,learn,lesson:()=>lesson(id),sources,progress:progressPage,exam};shell((renderer[page]||notFound)(),page);if(page==='exam'&&state.exam&&!state.exam.finished){updateTimer();examTimer=setInterval(updateTimer,1000);const e=byId(state.exam.ids[state.exam.index]);const db=await createEngine({SQL,level:e.level,seed:datasetById(e.dataset).seed+(e.setup?'\n'+e.setup:'')});const box=document.querySelector('#exam-table-content');if(box)box.innerHTML=db.tables().map(t=>dataTable(t.columns,t.rows,{caption:t.name})).join('');db.close();}}}
function updateLineNumbers(){const el=document.querySelector('#sql-editor');const numbers=document.querySelector('.line-numbers');if(el&&numbers){numbers.textContent=el.value.split('\n').map((_,i)=>i+1).join('\n');numbers.scrollTop=el.scrollTop;}}
function currentSql(){return document.querySelector('#sql-editor')?.value||'';}
function saveDraft(value){editorDirty=true;feedback=null;const feedbackBox=document.querySelector('#feedback-region');if(feedbackBox)feedbackBox.innerHTML='';const output=document.querySelector('#output-panel');const oldResult=route()[0]==='lab'?labResult:result;if(output&&oldResult)output.innerHTML="<p class=\"stale-notice\">SQL has changed. The result below is from the previous run. Run it again to update the result.</p>"+outputPanel(oldResult);if(route()[0]==='lab'){labSql=value;if(state.lab)state.lab.sql=value;}else if(activeId)state.drafts[activeId]=value;clearTimeout(saveTimer);saveTimer=setTimeout(persist,250);}
function setBusy(value){busy=value;document.querySelectorAll('[data-action="run"],[data-action="submit"]').forEach(b=>b.disabled=value);}
async function runSql(){if(busy)return;const isLab=route()[0]==='lab',sql=currentSql();if(!sql.trim()){toast("Write a SQL statement before running it.",true);document.querySelector('#sql-editor')?.focus();return;}saveDraft(sql);editorDirty=false;setBusy(true);let db;try{if(isLab){await ensureLab();db=labEngine;}else{const e=byId(activeId);db=await createEngine({SQL,level:e.level,seed:datasetById(e.dataset).seed+(e.setup?'\n'+e.setup:'')});}const output=db.run(sql,{level:state.level});if(isLab){labResult=output;state.lab={dataset:labDataset,sql:labSql,snapshot:labEngine.export()};persist();document.querySelector('#database-panel').innerHTML=databasePanel(displayTables(labEngine.tables(),datasetById(labDataset)));const status=document.querySelector('#lab-save-status');if(status)status.textContent="Experiment saved on this device";}else {result=output;exerciseTables=taskTables(db.tables(),byId(activeId));const dataPanel=document.querySelector('#database-panel');if(dataPanel)dataPanel.innerHTML=databasePanel(exerciseTables);}}catch(error){if(isLab)labResult={error:error.message};else result={error:error.message};}finally{if(!isLab)db?.close();setBusy(false);const output=document.querySelector('#output-panel');if(output)output.innerHTML=outputPanel(isLab?labResult:result);}}
function normalizePrediction(text,ordered){const lines=String(text).trim().split(/\r?\n/).filter(s=>s.trim()).map(s=>s.split(',').map(v=>v.trim().replace(/^['"]|['"]$/g,'')).join(','));return (ordered?lines:lines.sort()).join('\n');}
async function checkAnswer(e,value){if(e.kind==='sql')return gradeSql(SQL,e,datasetById(e.dataset),value);if(e.kind==='concept')return {passed:String(value)===String(e.answer),detail:String(value)===String(e.answer)?"Correct.":"That option does not match the scenario. Think about the purpose of fields, records and keys."};const passed=normalizePrediction(value,e.ordered)===normalizePrediction(e.expected,e.ordered);return {passed,detail:passed?"You predicted the query result correctly.":"The predicted result differs. Check the output fields, number of records, conditions and sorting. Use one record per line and omit the header."};}
async function submit(){if(busy)return;const e=byId(activeId);const value=e.kind==='sql'?currentSql():e.kind==='predict'?document.querySelector('#prediction').value:document.querySelector('input[name="concept"]:checked')?.value;if(value==null||!String(value).trim()){toast("Enter an answer first.",true);return;}state.drafts[e.id]=value;setBusy(true);try{feedback=await checkAnswer(e,value);if(feedback.got)result=feedback.got;recordAttempt(state,e.id,feedback.passed,{assisted:solutionSeen});persist();}catch(error){feedback={passed:false,detail:error.message};recordAttempt(state,e.id,false,{assisted:solutionSeen});persist();}finally{setBusy(false);document.querySelector('#feedback-region').innerHTML=feedbackHtml();if(document.querySelector('#output-panel'))document.querySelector('#output-panel').innerHTML=outputPanel(result);document.querySelector('#answer-feedback')?.focus({preventScroll:true});document.querySelector('#answer-feedback')?.scrollIntoView({behavior:'smooth',block:'nearest'});}}
function modal(title,html,actions=[]){const dialog=document.querySelector('#dialog');dialog.innerHTML=`<div class="dialog-header"><h2>${esc(title)}</h2><button class="icon-button" data-action="close-dialog" aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-body">${html}</div><div class="dialog-actions">${actions.map(a=>`<button class="button ${a.danger?'danger':a.primary?'primary':'secondary'}" data-dialog-action="${a.id}">${esc(a.label)}</button>`).join('')}</div>`;dialog.showModal();for(const a of actions)dialog.querySelector(`[data-dialog-action="${a.id}"]`).onclick=async()=>{dialog.close();await a.run();};}
async function changeDataset(id,sql){if(labEngine){labEngine.close();labEngine=null;}labDataset=id;labResult=null;tableIndex=0;state.lab=null;await ensureLab();labSql=sql||`SELECT *\nFROM ${datasetById(id).tables[0]};`;state.lab={dataset:id,sql:labSql,snapshot:labEngine.export()};persist();if(route()[0]==='lab')await render();else go('lab');}
function saveExamAnswer(submitted=false){const x=state.exam;if(!x||x.finished)return;const id=x.ids[x.index],e=byId(id);const value=e.kind==='concept'?document.querySelector('input[name="exam-concept"]:checked')?.value:document.querySelector('#exam-answer')?.value;if(value!=null)x.answers[id]={...(x.answers[id]||{}),value,submitted:submitted||x.answers[id]?.submitted};persist();}
function updateTimer(){const x=state.exam;if(!x||x.finished)return;const seconds=Math.max(0,Math.ceil((x.deadline-Date.now())/1000));const el=document.querySelector('#exam-clock');if(el)el.textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;if(seconds===0)finishExam();}
async function finishExam(){if(busy||!state.exam||state.exam.finished)return;if(route()[0]==='exam')saveExamAnswer();busy=true;clearInterval(examTimer);const x=state.exam;for(const id of x.ids){const e=byId(id),value=x.answers[id]?.value;let checked={passed:false};if(value!=null&&String(value).trim()){try{checked=await checkAnswer(e,value);}catch(error){checked={passed:false,detail:error.message};}recordAttempt(state,id,checked.passed);}x.answers[id]={...(x.answers[id]||{}),passed:checked.passed,detail:checked.detail};}x.finished=true;busy=false;persist();if(route()[0]==='exam')render();else toast("The timed challenge has ended. Open Practice → Timed challenge to see the results.");}
let installPrompt;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
document.addEventListener('click',async event=>{const b=event.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;if(b.disabled)return;
  if(action==='run')return runSql();if(action==='submit')return submit();
  if(action==='reload')return location.reload();
  if(action==='theme'){state.theme=state.theme==='dark'?'light':'dark';persist();document.documentElement.dataset.theme=state.theme;await render();return;}
  if(action==='close-dialog'){document.querySelector('#dialog').close();return;}
  if(action==='bookmark'){const id=b.dataset.id;state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];persist();b.setAttribute('aria-pressed',String(state.bookmarks.includes(id)));b.classList.toggle('bookmarked',state.bookmarks.includes(id));toast(state.bookmarks.includes(id)?"Bookmark added":"Bookmark removed");if(route()[0]==='practice'&&filters.status==='saved')updateTaskList();return;}
  if(action==='filter'){filters.status=b.dataset.value;return render();}if(action==='clear-filters'){filters={search:'',status:'all',kind:'all'};return render();}
  if(action==='review'){filters.status='wrong';filters.search='';go('practice');return;}
  if(action==='dataset'){if(state.lab)modal("Switch sample dataset", "<p>The new sample will replace your current lab data. Learning progress and exercise drafts will be kept.</p>",[{id:'cancel',label:"Keep current experiment",run:()=>{}},{id:'switch',label:"Switch dataset",primary:true,run:()=>changeDataset(b.dataset.id)}]);else await changeDataset(b.dataset.id);return;}
  if(action==='lesson-lab'){const l=lessons.find(x=>x.id===b.dataset.id);modal("Run the lesson example", "<p>Load this lesson's dataset and query, replacing the current lab data.</p>",[{id:'cancel',label:"Cancel",run:()=>{}},{id:'open',label:"Load example",primary:true,run:()=>changeDataset(l.dataset,l.example)}]);return;}
  if(action==='table'){tableIndex=Number(b.dataset.index);if(route()[0]==='lab')document.querySelector('#database-panel').innerHTML=databasePanel(displayTables(labEngine.tables(),datasetById(labDataset)));else if(exerciseTables){const dataPanel=document.querySelector('#database-panel');if(dataPanel)dataPanel.innerHTML=databasePanel(exerciseTables);}else{const e=byId(activeId),db=await createEngine({SQL,seed:datasetById(e.dataset).seed+(e.setup?'\n'+e.setup:''),level:e.level});document.querySelector('#database-panel').innerHTML=databasePanel(taskTables(db.tables(),e));db.close();}return;}
  if(action==='insert'){const el=document.querySelector('#sql-editor');if(!el)return;el.setRangeText(b.dataset.text,el.selectionStart,el.selectionEnd,'end');el.focus();saveDraft(el.value);updateLineNumbers();return;}
  if(action==='copy'){try{await navigator.clipboard.writeText(currentSql());toast("SQL copied");}catch{const el=document.querySelector('#sql-editor');el.focus();el.select();toast("SQL selected. Use your device's copy command.");}return;}
  if(action==='font'){document.querySelector('.editor-area').classList.toggle('large-font');return;}
  if(action==='reset-code'){modal("Restore starting SQL", "<p>Replace the current SQL text and keep the database as it is.</p>",[{id:'cancel',label:"Cancel",run:()=>{}},{id:'reset',label:"Restore template",primary:true,run:()=>{const el=document.querySelector('#sql-editor');el.value=route()[0]==='lab'?`SELECT *\nFROM ${datasetById(labDataset).tables[0]};`:byId(activeId).starter||'';saveDraft(el.value);updateLineNumbers();el.focus();}}]);return;}
  if(action==='reset-db'){modal("Restart this experiment", "<p>Restore the original sample data and remove added tables and data changes. Your SQL text will be kept.</p>",[{id:'cancel',label:"Keep current data",run:()=>{}},{id:'reset',label:"Reset sample data",primary:true,run:async()=>{labEngine.reset();labResult=null;tableIndex=0;state.lab={dataset:labDataset,sql:labSql,snapshot:labEngine.export()};persist();await render();toast("Sample data restored");}}]);return;}
  if(action==='hint'){const e=byId(activeId);hintsShown=Math.min(hintsShown+1,e.hints.length);state.attempts[e.id]={...(state.attempts[e.id]||{}),hints:hintsShown};persist();const container=document.querySelector('#hints');container.innerHTML=e.hints.slice(0,hintsShown).map((h,i)=>`<p><span>${i+1}</span>${esc(h)}</p>`).join('');b.disabled=hintsShown===e.hints.length;b.innerHTML=`${icon('help')} ${b.disabled?"All hints shown":`Show hint  ${hintsShown+1} / ${e.hints.length}`}`;return;}
  if(action==='solution'){const e=byId(activeId);modal("Think it through, then view the answer","<p>After revealing the answer, completing this task will count as assisted. You can try a hint first or continue to the explanation.</p>",[{id:'cancel',label:"Keep trying",run:()=>{}},{id:'reveal',label:"Show reference answer",primary:true,run:()=>{solutionSeen=true;state.attempts[e.id]={...(state.attempts[e.id]||{}),assisted:true};persist();modal("Explanation and answer",`<p>${esc(e.explanation)}</p><pre class="solution-code">${esc(e.kind==='concept'?e.options[e.answer]:e.kind==='predict'?e.expected:e.solution)}</pre><p class="small-note">Several SQL statements can produce a correct result. Focus on why the query works.</p>`,[{id:'close',label:"Back to task",primary:true,run:()=>{}}]);}}]);return;}
  if(action==='next'){const list=visibleExercises(),i=list.findIndex(e=>e.id===activeId);go(i<list.length-1?`exercise/${list[i+1].id}`:'progress');return;}
  if(action==='recovery'){download('querypath-recovery.json',localStorage.getItem(STORAGE_KEY+'.recovery')||'');return;}
  if(action==='export'){download(`querypath-backup-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2));toast("Learning backup exported");return;}
  if(action==='csv'){const r=route()[0]==='lab'?labResult:result;if(!r?.columns?.length)return;const quote=v=>`"${String(v??'').replace(/"/g,'""')}"`;download('query-results.csv','\uFEFF'+[r.columns,...r.rows].map(row=>row.map(quote).join(',')).join('\r\n'),'text/csv;charset=utf-8');return;}
  if(action==='source-filter'){sourceFilter=b.dataset.value;document.querySelector('#evidence-list').innerHTML=evidenceList();b.parentElement.querySelectorAll('button').forEach(el=>{el.classList.toggle('selected',el===b);el.setAttribute('aria-pressed',String(el===b));});return;}
  if(action==='templates'){const list=exercises.filter(e=>e.dataset===labDataset&&e.kind==='sql'&&e.level===state.level).slice(0,5);modal("Choose a question to explore",`<p>Loading a SQL template keeps your current data.</p>${list.map(e=>`<button class="template-option" data-template="${e.id}"><strong>${esc(e.title)}</strong><code>${esc(e.solution)}</code></button>`).join('')||"<p>Write a SELECT query to explore this dataset. Templates are available for other practice scopes.</p>"}`);document.querySelectorAll('[data-template]').forEach(el=>el.onclick=()=>{const e=byId(el.dataset.template);labSql=e.solution;document.querySelector('#sql-editor').value=labSql;saveDraft(labSql);updateLineNumbers();document.querySelector('#dialog').close();});return;}
  if(action==='install'){if(installPrompt){await installPrompt.prompt();installPrompt=null;return;}modal("Use QueryPath on your devices",`<p><strong>Desktop: </strong>Open the website to start learning. Supported browsers offer an install option in the address bar or browser menu.</p><p><strong>iPhone / iPad: </strong>Open the HTTPS website in Safari and choose Share → Add to Home Screen. On Android, use the install option in the browser menu.</p><p><strong>Offline: </strong>${offlineReady?"Core learning content is cached and ready to use offline.":"Core files are still being cached. Keep the first visit online. Offline caching and installation use HTTPS or localhost."}</p><p><strong>On the same Wi-Fi: </strong>A phone or tablet can use the network address printed by the computer's local server. Use HTTPS or localhost for offline PWA caching.</p><p class="small-note">Transfer progress between devices with exported backups. External paper links need an internet connection.</p>`,[{id:'ok',label:"Got it",primary:true,run:()=>{}}]);return;}
  if(action==='clear-progress'){modal("Clear this device's learning records","<p>This deletes task drafts, completed-task records, bookmarks and lab data. Export a backup first if you want to keep a copy.</p>",[{id:'cancel',label:"Cancel",run:()=>{}},{id:'export',label:"Export backup first",run:()=>download('querypath-backup.json',JSON.stringify(state,null,2))},{id:'clear',label:"Clear records",danger:true,run:()=>{localStorage.removeItem(STORAGE_KEY);location.reload();}}]);return;}
  if(action==='start-exam'){const list=visibleExercises();const shuffled=[...list].sort(()=>Math.random()-.5).slice(0,5);state.exam={ids:shuffled.map(e=>e.id),index:0,deadline:Date.now()+15*60000,answers:{},finished:false};persist();return render();}
  if(action==='exam-save'){saveExamAnswer(true);document.querySelector('#exam-save-note').textContent="Answer saved. You can keep editing.";toast("Answer saved");return;}
  if(action==='exam-next'){saveExamAnswer(true);state.exam.index++;persist();return render();}
  if(action==='exam-index'){saveExamAnswer();state.exam.index=Number(b.dataset.index);persist();return render();}
  if(action==='finish-exam'){modal("Finish this challenge", "<p>All entered answers will be checked. Unanswered tasks will remain incomplete.</p>",[{id:'cancel',label:"Keep working",run:()=>{}},{id:'finish',label:"Finish and view results",primary:true,run:finishExam}]);return;}
});
function updateTaskList(){document.querySelector('#task-list').innerHTML=exerciseCards(filteredExercises());document.querySelector('#task-count').textContent=`${filteredExercises().length} matching tasks`;}
document.addEventListener('input',e=>{if(e.target.id==='sql-editor'){saveDraft(e.target.value);updateLineNumbers();}if(e.target.id==='task-search'){filters.search=e.target.value;updateTaskList();}if(e.target.id==='prediction'){state.drafts[activeId]=e.target.value;persist();}if(e.target.id==='exam-answer')saveExamAnswer();});
document.addEventListener('change',async event=>{const el=event.target;if(el.id==='level-select'){state.level=el.value;if(state.level==='ig'&&state.year==='2029')state.year='2028';persist();if(route()[0]==='exercise'||route()[0]==='lesson')go('practice');else render();}if(el.id==='kind-filter'){filters.kind=el.value;updateTaskList();}if(el.name==='concept'){state.drafts[activeId]=el.value;persist();}if(el.name==='exam-concept')saveExamAnswer();if(el.id==='dataset-select'){const id=el.value;el.value=labDataset;modal("Switch dataset","<p>The new sample will replace the current lab data. Learning records and exercise drafts will be kept.</p>",[{id:'cancel',label:"Cancel",run:()=>{}},{id:'switch',label:"Switch dataset",primary:true,run:()=>changeDataset(id)}]);}if(el.id==='import-file'){const file=el.files[0];if(!file)return;if(file.size>8000000){toast("Choose a JSON backup smaller than 8 MB.",true);return;}try{const imported=validateBackup(JSON.parse(await file.text()));modal("Merge learning records",`<p>Found  ${Object.keys(imported.attempts).length}  task records and ${Object.keys(imported.drafts).length}  drafts. Progress and bookmarks will be merged, keeping the newer attempt for each task. Existing drafts and lab data will be kept.</p>`,[{id:'cancel',label:"Cancel",run:()=>{}},{id:'import',label:"Merge backup",primary:true,run:()=>{state=mergeBackup(state,imported);persist();render();toast("Learning records merged");}}]);}catch(error){toast(`Import failed: ${error.message}`,true);}el.value='';}});
document.addEventListener('keydown',e=>{if(e.target.id==='sql-editor'){if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();runSql();}if(e.key==='Escape'){e.target.dataset.escapeTab='true';}if(e.key==='Tab'&&e.target.dataset.escapeTab==='true'){delete e.target.dataset.escapeTab;return;}if(e.key==='Tab'&&!e.shiftKey){e.preventDefault();e.target.setRangeText('  ',e.target.selectionStart,e.target.selectionEnd,'end');saveDraft(e.target.value);updateLineNumbers();}}});
document.addEventListener('scroll',e=>{if(e.target.id==='sql-editor'){const numbers=document.querySelector('.line-numbers');if(numbers)numbers.scrollTop=e.target.scrollTop;}},true);
document.querySelector('#dialog').addEventListener('click',e=>{if(e.target===e.currentTarget)e.currentTarget.close();});
window.addEventListener('hashchange',()=>{clearTimeout(saveTimer);persist();render();window.scrollTo({top:0,behavior:'instant'});});
window.addEventListener('pagehide',()=>{clearTimeout(saveTimer);persist();});
window.addEventListener('online',()=>toast("Connection restored"));window.addEventListener('offline',()=>toast(offlineReady?"You are offline. Core learning content is still available.":"You are offline. Content already loaded is still available."));
async function boot(){await render();try{if(!window.initSqlJs)await new Promise((resolve,reject)=>{const script=document.querySelector('script[data-sql-runtime]');script.addEventListener('load',resolve,{once:true});script.addEventListener('error',()=>reject(new Error("The SQL engine could not load. Refresh the page to try again.")),{once:true});});SQL=await window.initSqlJs({locateFile:f=>assetUrl(`vendor/${f}`)});await render();if(loaded.warning)toast(loaded.warning,true);}catch(e){engineError=e.message;render();}try{const all=await Promise.all(['ig','as'].map(async code=>{const r=await fetch(assetUrl(`docs/research/${code}-papers.json`));if(!r.ok)throw new Error("Loading failed");return r.json();}));evidence=all.flat();if(route()[0]==='sources')document.querySelector('#evidence-list').innerHTML=evidenceList();}catch{}if('serviceWorker'in navigator&&window.isSecureContext){try{await navigator.serviceWorker.register(assetUrl('sw.js'),{scope:appBase.href});await navigator.serviceWorker.ready;offlineReady=true;const note=document.querySelector('.local-note span:last-child');if(note)note.textContent="Offline learning is ready";}catch{}}}
boot();
